package Jpractice.loop;

public class J1115_04 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		for(int i=1;i<=3;i++){
			for(int j=2;j>=2;j--){
				System.out.print(" ");
			}
			for(int k=1;k<=3;k++){
				System.out.print("*");
				}
			}
			System.out.println();
		}	
	}


